import re
from datetime import datetime

_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")


def _normalize_email(raw):
    s = raw.strip()
    m = re.search(r"<([^<>]*)>", s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            s = local + "@gmail.com"
    return s


def _is_valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    s = raw.lower()
    markers = [i for i in (s.find("x"), s.find("ext"), s.find("#")) if i != -1]
    if markers:
        s = s[:min(markers)]
    digits = "".join(c for c in s if c in "0123456789")
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    z = raw.strip()
    m = re.fullmatch(r"([0-9]{4,5})-[0-9]{4}", z)
    if m:
        z = m.group(1)
    if re.fullmatch(r"[0-9]{4}", z):
        z = "0" + z
    return z if re.fullmatch(r"[0-9]{5}", z) else ""


def _normalize_name(raw):
    s = raw.strip()
    if s and (s.isupper() or s.islower()):
        s = s.title()
    return s


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _pick(members, field):
    """Pick the best row for a field: non-empty, manual first, then most
    recent 'updated', then earliest input row. Returns None if no row qualifies."""
    cands = [r for r in members if r[field]]
    if not cands:
        return None
    # Stable multi-pass sort: the last sort is the primary key.
    cands = sorted(cands, key=lambda r: r["index"])
    cands = sorted(cands, key=lambda r: r["updated"], reverse=True)
    cands = sorted(cands, key=lambda r: not r["manual"])
    return cands[0]


def _merge_group(members):
    out = {}
    for field in ("first_name", "last_name", "zip", "email", "phone", "source"):
        best = _pick(members, field)
        out[field] = best[field] if best else ""
    out["tags"] = ";".join(sorted({t for r in members for t in r["tags"]}))
    out["opted_out"] = "Y" if any(r["opted_out"] for r in members) else "N"
    out["updated"] = max(r["updated"] for r in members).strftime("%Y-%m-%d")
    return out


def dedupe_contacts(rows):
    """Normalize, filter, and deduplicate CRM contact rows.

    Returns one dict per person, ordered by each person's earliest input row.
    Each dict has keys: first_name, last_name, zip, email, phone, source,
    tags, opted_out ("Y"/"N"), updated ("YYYY-MM-DD").
    """
    # Step 1: normalize each row and drop rows with no valid email or phone.
    recs = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row.get("email", ""))
        phone = _normalize_phone(row.get("phone", ""))
        email_ok = _is_valid_email(email)
        phone_ok = _is_valid_phone(phone)
        if not email_ok and not phone_ok:
            continue

        source = row.get("source", "").strip().lower()
        tags = (t.strip().lower() for t in re.split(r"[;,]", row.get("tags", "")))
        recs.append({
            "index": idx,
            "first_name": _normalize_name(row.get("first_name", "")),
            "last_name": _normalize_name(row.get("last_name", "")),
            "email": email if email_ok else "",
            "phone": phone if phone_ok else "",
            "zip": _normalize_zip(row.get("zip", "")),
            "source": source,
            "manual": source == "manual",
            "updated": _parse_updated(row["updated"]),
            "opted_out": row.get("opted_out", "").strip().lower() in _OPT_OUT_VALUES,
            "tags": [t for t in tags if t],
        })

    # Step 2: union-find so that matching is transitive.
    parent = list(range(len(recs)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    by_email = {}
    by_phone_last = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in by_email:
                union(by_email[r["email"]], i)
            else:
                by_email[r["email"]] = i
        if r["phone"] and r["last_name"]:
            key = (r["phone"], r["last_name"].casefold())
            if key in by_phone_last:
                union(by_phone_last[key], i)
            else:
                by_phone_last[key] = i

    # Step 3: group rows; dict insertion order follows each group's earliest row.
    groups = {}
    for i, r in enumerate(recs):
        groups.setdefault(find(i), []).append(r)

    return [_merge_group(members) for members in groups.values()]
